@Test
public void testEnvironmentVariablesAreInterpolated() throws Exception {
    ToolchainsBuildingRequest request = new DefaultToolchainsBuildingRequest();
    request.setUserToolchainsSource(new StringSource(""));
    Map<String, String> props = new HashMap<>();
    props.put("key", "${env.testKey}");
    XmlNodeImpl configurationChild = new XmlNodeImpl("jdkHome", "${env.testKey}", null, null, null);
    XmlNodeImpl configuration = new XmlNodeImpl("configuration", null, null, Collections.singletonList(configurationChild), null);
    ToolchainModel toolchain = ToolchainModel.newBuilder().type("TYPE").provides(props).configuration(configuration).build();
    PersistedToolchains persistedToolchains = PersistedToolchains.newBuilder().toolchains(Collections.singletonList(toolchain)).build();
    doReturn(persistedToolchains).when(toolchainsReader).read(any(InputStream.class), ArgumentMatchers.<String, Object>anyMap());
    ToolchainsBuildingResult result = toolchainBuilder.build(request);
    String interpolatedValue = "testValue";
    assertEquals(interpolatedValue, result.getEffectiveToolchains().getToolchains().get(0).getProvides().get("key"));
    org.codehaus.plexus.util.xml.Xpp3Dom toolchainConfiguration = (org.codehaus.plexus.util.xml.Xpp3Dom) result.getEffectiveToolchains().getToolchains().get(0).getConfiguration();
    assertEquals(interpolatedValue, toolchainConfiguration.getChild("jdkHome").getValue());
    assertNotNull(result.getProblems());
    assertEquals(0, result.getProblems().size());
}

